@Component({
  selector: 'ap-button',
  imports: [CommonModule, ApIconComponent],
  templateUrl: './ap-button.component.html',
  styleUrl: './ap-button.component.css',
})
export class ApButtonComponent {
  showLabel = input<boolean>(true);
  label = input<string>('');
  icon = input<string>('');
  /** 圖標位置 */
  iconPos = input<'left' | 'right'>('left');
  /** 按鈕類型 */
  type = input<'button' | 'submit' | 'reset'>('button');
  size = input<'x-small' | 'small' | 'medium' | 'large'>('medium');
  variant = input<ButtonVariant>('content');
  accentColor = input<ButtonAccentColor>('orange');
  disabled = input<boolean>(false);
  loading = input<boolean>(false);
  link = input<boolean>(false);

  /**
   * @deprecated 請使用 clicked 事件，onClick 將會在未來版本移除
   */
  onClick = output<Event>();
  /** 受到Disable保護的Click */
  clicked = output<Event>();
  get buttonClasses(): string {
    const classes: string[] = [
      'inline-flex',
      'items-center',
      'justify-center',
      'font-sans',
      'font-semibold',
      'outline-none',
    ];
    /** 尺寸 */
    if (this.size() === 'x-small') {
      classes.push('gap-0.5', 'p-1', 'text-xs', 'leading-4');
    } else if (this.size() === 'small') {
      classes.push('gap-1', 'p-1.5', 'text-sm', 'leading-5');
    } else if (this.size() === 'large') {
      classes.push('gap-2', 'p-2.5', 'text-xl', 'leading-7');
    } else {
      classes.push('gap-1.5', 'p-2', 'text-base', 'leading-6');
    }

    const isRounded =
      this.variant() === 'content-rounded' ||
      this.variant() === 'outlined-rounded';

    if (isRounded) {
      classes.push('rounded-full');
    } else {
      if (this.size() === 'x-small') {
        classes.push('rounded');
      } else if (this.size() === 'small') {
        classes.push('rounded-md');
      } else if (this.size() === 'large') {
        classes.push('rounded-[10px]');
      } else {
        classes.push('rounded-lg');
      }
    }

    const isText = this.variant() === 'text';
    const isOutlined =
      this.variant() === 'outlined' ||
      this.variant() === 'outlined-rounded';
    const isRaised = this.variant() === 'raised';

    if (isText) {
      this.applyTextClasses(classes);
    } else if (isOutlined) {
      this.applyOutlinedClasses(classes);
    } else {
      this.applyDefaultClasses(classes, isRaised);
    }

    if (this.disabled() || this.loading()) {
      classes.push('opacity-60', 'cursor-not-allowed');
    } else {
      classes.push('cursor-pointer');
    }

    return classes.join(' ');
  }

  get iconSizeClass(): string {
    if (this.size() === 'x-small') return 'size-3';
    if (this.size() === 'small') return 'size-4';
    if (this.size() === 'large') return 'size-7';
    return 'size-6';
  }

  private applyDefaultClasses(classes: string[], isRaised: boolean): void {
    const colorClasses = FILLED_COLOR_CLASSES[this.accentColor()];
    classes.push('border', ...colorClasses.base);

    if (!this.disabled() && !this.loading()) {
      classes.push(...colorClasses.interactive);
    }

    if (isRaised && colorClasses.shadow) {
      classes.push(...colorClasses.shadow);
    }
  }

  private applyTextClasses(classes: string[]): void {
    const colorClasses = TEXT_COLOR_CLASSES[this.accentColor()];
    classes.push('bg-transparent', 'border-0', ...colorClasses.base);

    if (!this.disabled() && !this.loading()) {
      classes.push(...colorClasses.interactive);
    }
  }

  private applyOutlinedClasses(classes: string[]): void {
    const colorClasses = OUTLINED_COLOR_CLASSES[this.accentColor()];
    classes.push('border', 'bg-zinc-900', ...colorClasses.base);

    if (!this.disabled() && !this.loading()) {
      classes.push(...colorClasses.interactive);
    }
  }

  handleClick(event: Event): void {
    if (!this.disabled() && !this.loading()) {
      this.onClick.emit(event);
      this.clicked.emit(event);
    }
  }
}
